AccountBetTransaction:
query AccountBetTransaction($transactionId: ID!) {
  accountBetTransaction(transactionId: $transactionId) {
    ...AccountPendingResultedBet
    ... on AccountPendingResultedBet {
      details {
        ... on AccountBetRacingSingle {
          blackbookInfo {
            categoryIcon {
              localAssetName(platform: DESKTOP)
            }
            entrant {
              id
              name
            }
            entry {
              id
              comment
              created
              updated
            }
            runnerID
          }
        }
      }
    }
    ...AccountBetTransactionLeg
    ...AccountBetPlayAgain
  }
}

