AccountGetBetCombinations:
query AccountGetBetCombinations($id: ID!, $groupId: String, $first: Int = 100, $after: String) {
  accountGetBetCombinations(
    id: $id
    groupId: $groupId
    first: $first
    after: $after
  ) {
    combinations: nodes {
      id
      entrantNumbers
      odds
    }
    pageInfo {
      hasNextPage
      endCursor
    }
  }
}

AccountGetBetTransaction:
query AccountGetBetTransaction($id: ID!, $groupId: String, $includeCashOutCheck: Boolean = false, $includeEntrantTrackers: Boolean = false, $includeMultisPreview: Boolean = false, $eventId: UUID) {
  accountGetBetTransaction(
    id: $id
    groupId: $groupId
    includeCashOutCheck: $includeCashOutCheck
    includeEntrantTrackers: $includeEntrantTrackers
    eventId: $eventId
  ) {
    id
    acceptAmount
    created
    returnId
    transactionType
    bet {
      ...AccountBet
      cashOutAvailable
      returnedTime
      deductionsApplied
      final
      ...AccountBetBlackbook
      playAgain {
        odds {
          decimal
          formatted
          variant
        }
        strategy
      }
      legs {
        ...AccountBetLeg
      }
    }
  }
}

