ExperienceEventCards:
query ExperienceEventCards($firstInviteOnlyEvents: Int = 10, $afterInviteOnlyEvents: String, $firstLimitedAvailabilityEvents: Int = 10, $afterLimitedAvailabilityEvents: String, $firstEOIEvents: Int = 10, $afterEOIEvents: String, $firstUpcomingEvents: Int = 10, $afterUpcomingEvents: String, $firstExclusivePromotions: Int = 2, $subdivision: Subdivision) {
  experienceHubHomePage(
    firstInviteOnlyEvents: $firstInviteOnlyEvents
    afterInviteOnlyEvents: $afterInviteOnlyEvents
    firstLimitedAvailabilityEvents: $firstLimitedAvailabilityEvents
    afterLimitedAvailabilityEvents: $afterLimitedAvailabilityEvents
    firstEOIEvents: $firstEOIEvents
    afterEOIEvents: $afterEOIEvents
    firstUpcomingEvents: $firstUpcomingEvents
    afterUpcomingEvents: $afterUpcomingEvents
  ) {
    inviteOnlyEventCards(
      first: $firstInviteOnlyEvents
      after: $afterInviteOnlyEvents
    ) {
      ...ExperienceInviteOnlyEventCardCollection
    }
    limitedAvailabilityEventCards(
      first: $firstLimitedAvailabilityEvents
      after: $afterLimitedAvailabilityEvents
    ) {
      nodes {
        ...ExperienceEventCard
      }
    }
    upcomingEventCards(first: $firstUpcomingEvents, after: $afterUpcomingEvents) {
      nodes {
        ...ExperienceEventCard
      }
    }
    expressionOfInterestEventCards(first: $firstEOIEvents, after: $afterEOIEvents) {
      nodes {
        ...ExperienceEventCard
      }
    }
  }
  experiencePromotions(
    first: $firstExclusivePromotions
    subdivision: $subdivision
    availableOn: DESKTOP_ONLY
  ) {
    promotions {
      ...ExperiencePromotion
    }
    promotionCount
  }
  client {
    coupons {
      ...OffersCoupon
    }
    offers {
      ...ClientOffer
    }
  }
}

