RacingBetBuilderMeeting:
query RacingBetBuilderMeeting($meetingId: ID!, $shouldFetchProductGroups: Boolean = false) {
  meeting: node(id: $meetingId) {
    ... on RacingMeeting {
      id
      name
      nextToGoRace {
        id
      }
      races: racesConnection {
        nodes {
          id
          name
          number
          actualStart
          advertisedStart
          meeting {
            id
          }
          markets: marketsConnection(
            types: [FINAL_FIELD]
            first: 1
            shouldFetchToteExotics: $shouldFetchProductGroups
          ) {
            nodes {
              id
              status
              type
              productGroups @include(if: $shouldFetchProductGroups) {
                id
                placeProducts {
                  id
                }
                winProducts {
                  id
                }
              }
            }
          }
        }
      }
      availableCompounds: compoundsConnection(includeClosed: false) {
        nodes {
          id
          type
          productType {
            ...PricingProductType
          }
          races: racesConnection(first: 6) {
            nodes {
              id
              number
            }
          }
        }
      }
    }
  }
}

