SportingLandingScreen:
query SportingLandingScreen($includeCategories: Boolean = false, $statuses: [SportingMarketStatus!] = [OPEN], $includeQuicklinks: Boolean = false, $quicklinksShortTitle: Boolean = true, $platform: QuickLinkPlatform = MOBILE, $excludeCategoryIds: [UUID!], $includeFeaturedEvents: Boolean = false, $featuredEventsEventCount: Int, $featuredEventsType: QuickLinkType = FEATURED, $includeUpcomingEvents: Boolean = false, $upcomingEventsCount: Int, $upcomingEventsGroupBy: SportingEventsGroup = UNSPECIFIED, $includeFeaturedComps: Boolean = false, $featuredCompCount: Int, $featuredCompStatuses: [SportingMarketStatus!] = [OPEN], $featuredCompEventCount: Int, $includeInPlayEvents: Boolean = false, $inPlayEventCount: Int) {
  categories: sportingCategories(statuses: $statuses) @include(if: $includeCategories) {
    ...SportingCategory
  }
  quickLinks(
    type: SPORTS
    platform: $platform
    includeRacing: false
    includeSporting: true
    includeUncategorised: false
    excludeCategoryIds: $excludeCategoryIds
  ) @include(if: $includeQuicklinks) {
    nodes {
      ...QuickLink
    }
  }
  featuredEvents: quickLinks(
    first: $featuredEventsEventCount
    type: $featuredEventsType
    includeRacing: false
    includeSporting: true
    includeUncategorised: false
    excludeCategoryIds: $excludeCategoryIds
  ) @include(if: $includeFeaturedEvents) {
    nodes {
      ...SportingFeaturedEvent
    }
  }
  upcomingEvents: sportingEvents(
    first: $upcomingEventsCount
    eventTypes: [MATCH]
    statuses: [OPEN]
    groupBy: $upcomingEventsGroupBy
    excludeCategoryIds: $excludeCategoryIds
  ) @include(if: $includeUpcomingEvents) {
    ...SportingFilteredEvents
  }
  featuredCompetitions: sportingFeaturedCompetitions(
    first: $featuredCompCount
    excludeCategoryIds: $excludeCategoryIds
  ) @include(if: $includeFeaturedComps) {
    nodes {
      ...SportingNextToGoCompetition
    }
  }
  inPlayEvents: sportingEvents(
    first: $inPlayEventCount
    eventTypes: [MATCH, OUTRIGHT]
    statuses: [LIVE]
    excludeCategoryIds: $excludeCategoryIds
  ) @include(if: $includeInPlayEvents) {
    events {
      nodes {
        ...SportingCompetitionLiveEvent
      }
    }
  }
}

